  "landmark-brandenburg-gate": {
    de: [
      { q: "Wer krönt das Brandenburger Tor?", a: "Die Quadriga, ein Streitwagen, der von der Friedensgöttin Eirene gelenkt wird." },
      { q: "Wann wurde das Tor erbaut?", a: "Zwischen 1788 und 1791 im frühklassizistischen Stil." },
      { q: "Wie viele Durchfahrten hat das Tor?", a: "Es besitzt fünf Durchfahrten, von denen die mittlere früher dem König vorbehalten war." },
      { q: "Was geschah 1806 mit der Quadriga?", a: "Napoleon brachte sie als Kriegsbeute nach Paris, von wo sie 1814 zurückkehrte." },
      { q: "An welchem berühmten Platz steht das Tor?", a: "Am Pariser Platz im Zentrum Berlins." }
    ],
    hu: [
      { q: "Mi díszíti a Brandenburgi kapu tetejét?", a: "A Quadriga, egy harci szekér, amelyet Eiréné békistennő irányít." },
      { q: "Mikor épült a kapu?", a: "1788 és 1791 között kora klasszicista stílusban." },
      { q: "Hány átjárója van a kapunak?", a: "Öt átjárója van, amelyek közül a középső korábban a királynak volt fenntartva." },
      { q: "Mi történt a Quadrigával 1806-ban?", a: "Napóleon hadizsákmányként Párizsba vitte, ahonnan 1814-ben tért vissza." },
      { q: "Melyik híres téren áll a kapu?", a: "A Pariser Platzon, Berlin központjában." }
    ],
    ro: [
      { q: "Ce decorează vârful Porții Brandenburg?", a: "Cvadriga, un car condus de zeița păcii, Eirene." },
      { q: "Când a fost construită poarta?", a: "Între 1788 și 1791, în stil neoclasiс timpuriu." },
      { q: "Câte pasaje are poarta?", a: "Are cinci pasaje, cel din mijloc fiind rezervat odinioară regelui." },
      { q: "Ce s-a întâmplat cu Cvadriga în 1806?", a: "Napoleon a dus-o ca pradă de război la Paris, de unde a revenit în 1814." },
      { q: "În ce piață faimoasă se află poarta?", a: "În Pariser Platz, în centrul Berlinului." }
    ],
    en: [
      { q: "What crowns the top of the Brandenburg Gate?", a: "The Quadriga, a chariot driven by Eirene, the goddess of peace." },
      { q: "When was the gate built?", a: "Between 1788 and 1791 in an early classical style." },
      { q: "How many passages does the gate have?", a: "It has five passages, the middle of which was formerly reserved for the king." },
      { q: "What happened to the Quadriga in 1806?", a: "Napoleon took it to Paris as a spoil of war, and it was returned in 1814." },
      { q: "In which famous square does the gate stand?", a: "In Pariser Platz in the center of Berlin." }
    ]
  },
